/**
 * The filled glyph of a role a member draws filled, from the filled set of Compose’s Material icons
 * (`FILLED_SYMBOLS` in `packages/native/src/kotlin.ts`), and `null` for every other role.
 */
internal val PMIconRole.filledVector: ImageVector?
    get() = when (this) {
        PMIconRole.Rating -> Icons.Filled.Star
        else -> null
    }
